with exploded as (select id, customer_id, coupon_codes, inline(items) from carts) select case when qty >= 5 then 'PREMIUM' else 'STANDARD' end as qty_tier, promo, count(distinct id) as distinct_ids, sum(price) as total_price, count_if(promo = 'WELCOME5') as welcome5_events, approx_percentile(qty, array(0.25, 0.5, 0.75)) as qty_quartiles, count(case when promo = 'VIP' then 1 end) as vip_count, count(distinct id) as distinct_ids_2 from exploded group by case when qty >= 5 then 'PREMIUM' else 'STANDARD' end, promo;
